// Long quiet stretches are skipped: a ride, or a settled scene apart from its last seconds.\n  function joinMoment(e, real){\n    if (!e) return;\n    const t0 = performance['now'](), list = [...TL.values()], p = list[list.indexOf(e) - 1], where = x => [x.ev.location || 'apartment', x.ev.action];\n    let sim = Math.min(stepTo(real), Math.ceil(e.start / STEP) * STEP), n = 0; const begin = sim; SIM = sim;\n    // the moment before, settled: a few seconds of it put him where he really was (pacing, on an errand)\n    if (p){ sim -= 12000; SIM = sim; NEXT_RIDE = p.ev.ride || null; setState(...where(p), true, p.ev.with || null); render(wall());\n      while (sim < begin){ sim += STEP; SIM = sim; update(STEP/1000, sim); if (++n % 3 === 0) render(wall()); } }\n    NEXT_RIDE = e.ev.ride || null; setState(...where(e), !p, e.ev.with || null); actor.hint = homeHint(e.ev.text); actor.hintUntil = e.end;\n    while (sim < real && n < 15000){\n      if (actor.rideUntil && actor.rideUntil - 2*STEP > sim) sim = Math.min(stepTo(real), stepTo(actor.rideUntil) - STEP);\n      else if (rideQuiet() && sim < real - 8000) sim = stepTo(real - 8000);\n      sim += STEP; SIM = sim; update(STEP/1000, sim); if (++n % 3 === 0) render(wall());\n    }\n    simT = sim; SIM = null; e.ev._joined = true; window.__ishaiJoinMs = performance['now']() - t0;\n  }\n  function frame(){\n    if (BUILDER) return;\n    const grid = stepTo(NOW());\n    if (simT === null) simT = grid;\n    if (grid - simT > 3000){\n      const e = !forceLoc && !PREVIEW && !demoMode ? momentAt(grid) : null;\n      if (e) joinMoment(e, grid); else simT = grid;\n    }\n    advance(grid);\n    render(wall()); placeSay(); Sound.setAmbience(ambienceKey());\n  }\n  // animation frames stop on a hidden page; while the pop-out window is open a worker's timer takes over\n  function loop(){ if (!POP.on || !document.hidden) frame(); requestAnimationFrame(loop); }\n  // ---- speech bubble above whoever is talking ----\n  const SAY = { who:null, text:'', until:0 };\n  function showSay(who, text){ SAY.who = who; SAY.text = text; SAY.until = NOW() + 60000; }\n  function holdSay(ms){ SAY.until = NOW() + ms; }\n  function placeSay(){\n    const el = $('say');\n    if (!SAY.who || NOW() > SAY.until || actor.switching){ el.hidden = true; return; }\n    const sp = speaker(SAY.who), head = HEADS[SAY.who];\n    const remote = CAST[SAY.who] && CAST[SAY.who].remote;\n    if (!head && !remote && !(SAY.who === 'radio' || SAY.who === 'tv' || (actor.action === 'phoning' && actor.with === SAY.who))){ el.hidden = true; return; }\n    $('sayWho').textContent = (head ? '' : SAY.who==='radio' ? '\\u{1F4FB} ' : SAY.who==='tv' ? '\\u{1F4FA} ' : remote && actor.with !== SAY.who ? '\\u2709 ' : '\\u260E ') + sp.name;\n    el.style.setProperty('--who', sp.ink); el.style.setProperty('--whoInk', inkText(sp.ink));\n    let txt = SAY.text; if (txt.length > 110 && SAY.who !== 'radio' && SAY.who !== 'tv'){ const cut = txt.slice(-105); txt = '\\u2026' + cut.slice(cut.indexOf(' ') + 1); }   // long lines: the bubble shows the latest part (the full line is in the chat)\n    $('sayText').textContent = txt;\n    el.hidden = false;\n    const cw = cv.clientWidth, ch = cv.clientHeight, top = cv.offsetTop;\n    if (head){\n      el.classList.remove('edge');\n      const px = head.x / W * cw, py = (head.y - 2) / H * ch + top;\n      // someone standing close by: the bubble opens to the far side, so it doesn't cover them\n      const other = Object.entries(HEADS).find(([id, h]) => id !== SAY.who && Math.abs(h.x - head.x) < 34 && Math.abs(h.y - head.y) < 20);\n      const half = el.offsetWidth / 2, side = other ? (other[1].x > head.x ? -1 : 1) : 0;\n      const left = Math.max(half + 6, Math.min(cw - half - 6, px + side * (half - 16)));\n      el.style.left = (left + cv.offsetLeft) + 'px'; el.style.top = Math.max(el.offsetHeight + 4, py) + 'px';\n      el.style.setProperty('--tail', Math.max(10, Math.min(el.offsetWidth - 10, px - left + half)) + 'px');\n    } else { // on the phone / not in the room: a bubble at the screen edge\n      el.classList.add('edge'); el.style.left = (cv.offsetLeft + cw - el.offsetWidth/2 - 8) + 'px'; el.style.top = (top + 40 + el.offsetHeight) + 'px';\n    }\n  }\n  setInterval(()=>{ $('clock').textContent = fmtClock.format(new Date(NOW())); }, 500);\n  $('clock').textContent = fmtClock.format(new Date(NOW()));\n\n  // ================= sound (Web Audio, generated in code, no files) =================\n  const Sound = (() => {\n    let ac = null, out = null, mode = 'off', amb = null, ambKey = '', wanted = '', brown = null, white = null;\n    const MODES = ['off','blips','voices'];\n    const LABELS = {off:'SOUND: OFF', blips:'SOUND: BLIPS', voices:'SOUND: VOICES'};\n    function init(){\n      if (ac) return true;\n      const AC = window.AudioContext || window.webkitAudioContext; if (!AC) return false;\n      ac = new AC(); out = ac.createGain(); out.gain.value = .6; out.connect(ac.destination);\n      const n = ac.sampleRate * 2; brown = ac.createBuffer(1,n,ac.sampleRate); white = ac.createBuffer(1,n,ac.sampleRate);\n      const d = brown.getChannelData(0), w = white.getChannelData(0); let last = 0;\n      for (let i=0;i<n;i++){ const r = Math.random()*2-1; w[i] = r; last = (last + .02*r)/1.02; d[i] = last*3.5; }\n      return true;\n    }\n    const on = () => !!ac && mode !== 'off';\n    function env(gn, t0, a, peak, dur){ gn.gain.setValueAtTime(.0001,t0); gn.gain.exponentialRampToValueAtTime(peak,t0+a); gn.gain.exponentialRampToValueAtTime(.0001,t0+dur); }\n    function tone(freq, dur, type='square', vol=.05, when=0, dest=out, slide=0){\n      const t0 = ac.currentTime + Math.max(0,when), o = ac.createOscillator(), gn = ac.createGain();\n      o.type = type; o.frequency.setValueAtTime(freq, t0);\n      if (slide) o.frequency.exponentialRampToValueAtTime(Math.max(30, freq*slide), t0+dur);\n      env(gn, t0, .005, vol, dur); o.connect(gn).connect(dest); o.start(t0); o.stop(t0+dur+.03);\n    }\n    function noise(dur, o={}){\n      const {vol=.05, type='bandpass', freq=1000, q=1, when=0, buf=white, sweep=null, dest=out} = o;\n      const t0 = ac.currentTime + Math.max(0,when), src = ac.createBufferSource(), f = ac.createBiquadFilter(), gn = ac.createGain();\n      src.buffer = buf; f.type = type; f.frequency.setValueAtTime(freq,t0); f.Q.value = q;\n      if (sweep){ f.frequency.exponentialRampToValueAtTime(sweep[0], t0+dur*.5); f.frequency.exponentialRampToValueAtTime(sweep[1], t0+dur); }\n      env(gn, t0, Math.min(.4, dur*.35), vol, dur); src.connect(f).connect(gn).connect(dest);\n      src.start(t0, Math.random()); src.stop(t0+dur+.05);\n    }\n\n    // ---- character voices ----\n    const VOICE = {\n      zohar:{f:440,type:'square',pitch:1.35,rate:1.15}, oren:{f:150,type:'triangle',pitch:.7,rate:.95},\n      ishai:{f:200,type:'square',pitch:1,rate:1}, levi:{f:520,type:'triangle',pitch:1.6,rate:1.15},\n      noa:{f:330,type:'square',pitch:1.25,rate:1.1}, avi:{f:120,type:'sawtooth',pitch:.6,rate:.85},\n      dana:{f:280,type:'triangle',pitch:1,rate:.8}, narrator:{f:160,type:'triangle',pitch:.9,rate:1.05},\n      radio:{f:240,type:'square',pitch:1.1,rate:1.15}, tv:{f:180,type:'triangle',pitch:.95,rate:1.1},\n      dj_benny:{f:240,type:'square',pitch:1.1,rate:1.18}, dj_shira:{f:360,type:'triangle',pitch:1.4,rate:1.05}, dj_yoni:{f:130,type:'triangle',pitch:.75,rate:.9}\n    };\n    const hash = id => { let h = 0; for (const ch of String(id)) h = (h*31 + ch.charCodeAt(0)) >>> 0; return h; };\n    function voiceOf(id){ if (VOICE[id]) return VOICE[id]; const h = hash(id);\n      return {f:140+h%380, type:['square','triangle','sawtooth'][h%3], pitch:.6+(h%100)/100, rate:.85+(h%30)/100}; }\n    let n = 0;\n    function blip(id, ch){\n      TALK_AT = NOW();\n      if (!on() || mode !== 'blips' || !/[a-z0-9]/i.test(ch) || (n++ % 2)) return;\n      const v = voiceOf(id); tone(v.f*(.9+Math.random()*.25), .05, v.type, v.type==='sawtooth' ? .025 : .04);\n    }\n    function key(ch){ if (on() && mode==='blips' && ch!==' ' && Math.random()<.45) noise(.012,{vol:.02,type:'highpass',freq:3000}); }\n    let voices = [], voiceState = 'not tried', blocked = false;\n    const loadVoices = () => { try { voices = speechSynthesis.getVoices().filter(v => /^en/i.test(v.lang)); } catch(e){} };\n    if ('speechSynthesis' in window){ loadVoices(); speechSynthesis.onvoiceschanged = loadVoices; }\n    function say(id, text){\n      if (!on() || mode !== 'voices' || !('speechSynthesis' in window)) return Promise.resolve();\n      return new Promise(res => {\n        const v = voiceOf(id), to = setTimeout(res, 4000 + text.length*120); const done = () => { clearTimeout(to); res(); };\n        saying++; let once = false; const fin = () => { if (!once){ once = true; saying--; } done(); };\n        setTimeout(() => { if (!once){ once = true; saying--; } }, 4000 + text.length*120);\n        // the speaker's own voice first; a voice that fails or never starts gives way once to the device's default voice\n        const speak = (own) => {\n          const u = new SpeechSynthesisUtterance(text); let started = false;\n          if (own && voices.length) u.voice = voices[hash(id) % voices.length];\n          u.pitch = Math.min(2, Math.max(0, v.pitch)); u.rate = v.rate; u.volume = .9;\n          const fallback = () => { u.onerror = u.onend = null; try { speechSynthesis.cancel(); } catch(e){} speak(false); };\n          u.onstart = () => { started = true; voiceState = own ? 'speaking' : 'speaking (default voice)'; };\n          u.onend = fin;\n          u.onerror = e => { const why = e && e.error || 'error'; voiceState = 'failed: ' + why;\n            if (why === 'not-allowed'){ blocked = true; btn.textContent = 'TAP FOR VOICES'; return fin(); }\n            if (why === 'canceled' || why === 'interrupted' || !own || started) return fin();\n            fallback(); };\n          try { speechSynthesis.resume(); } catch(e){}\n          speechSynthesis.speak(u);\n          if (own) setTimeout(() => { if (!started && !once){ voiceState = 'no start: ' + (u.voice ? u.voice.name : 'default'); fallback(); } }, 2500);\n        };\n        speak(true);\n      });\n    }\n\n    // ---- room sounds ----\n    // ---- live music for the radio: a music-only internet station (falls back to the chiptune) ----\n    let radioEl = null, radioVol = .55, placeVol = 1, djDown = false, saying = 0, volOk = null;\n    function streamStart(a, kind){\n      const st = radioPick(kind); if (!st) return false;\n      if (!radioEl){ radioEl = new Audio(); radioEl.preload = 'none'; radioEl.addEventListener('error', () => { if (radioEl.src) radioFail(radioEl.dataset.url); }); }\n      radioEl.dataset.url = st.url; radioEl.dataset.held = ''; radioEl.src = st.url; radioEl.volume = radioVol * placeVol;\n      radioEl.play().catch(e => { if (e && e.name !== 'AbortError') radioFail(st.url); });\n      a.audio = radioEl; a.station = st; return true;\n    }\n    function restartAmb(){ ambKey = ''; setAmbience(wanted); }\n    const streaming = () => amb && amb.audio ? amb.station : null;\n    function stopAmb(){\n      if (!amb) return; const a = amb; amb = null; a.alive = false;\n      if (a.audio){ a.audio.pause(); a.audio.removeAttribute('src'); try { a.audio.load(); } catch(e){} }\n      a.gain.gain.setTargetAtTime(.0001, ac.currentTime, .3);\n      setTimeout(() => a.nodes.forEach(x => { try { x.stop(); } catch(e){} try { x.disconnect(); } catch(e){} }), 1600);\n    }\n    function setAmbience(k){\n      wanted = k;\n      if (!ac || k === ambKey) return;\n      ambKey = k; stopAmb(); if (mode === 'off') return;\n      const [loc, extra, tod, wx] = k.split('|');\n      placeVol = loc === 'cafe' ? .22 : loc === 'bar' ? .85 : 1;\n      const a = {nodes:[], alive:true, gain: ac.createGain()}; amb = a;\n      a.gain.gain.value = .0001; a.gain.connect(out); a.gain.gain.setTargetAtTime(tod==='night' ? .6 : 1, ac.currentTime, .5);\n      const dest = a.gain;\n      const bed = (buf, type, freq, vol) => { const src = ac.createBufferSource(), f = ac.createBiquadFilter(), gn = ac.createGain();\n        src.buffer = buf; src.loop = true; f.type = type; f.frequency.value = freq; gn.gain.value = vol;\n        src.connect(f).connect(gn).connect(dest); src.start(); a.nodes.push(src); };\n      const loop = (ms, jit, fn) => { const step = () => { if (!a.alive) return; fn(); setTimeout(step, ms + Math.random()*jit); };\n        setTimeout(step, 300 + Math.random()*ms); };\n      const hum = (f, vol) => { const o = ac.createOscillator(), gn = ac.createGain(); o.frequency.value = f; gn.gain.value = vol; o.connect(gn).connect(dest); o.start(); a.nodes.push(o); };\n\n      if (loc === 'static' || loc === 'offscreen') bed(white, 'highpass', 2500, loc==='static' ? .07 : .035);\n      else if (loc === 'apartment'){\n        bed(brown, 'lowpass', 220, .05);\n        if (tod === 'night') loop(1000, 0, () => noise(.012,{vol:.04,type:'bandpass',freq:4200,q:6,dest}));\n      } else if (loc === 'bathroom'){ bed(brown,'lowpass',260,.04); hum(118,.006);   // extractor fan\n        if (extra !== 'shower') loop(2600, 1800, () => tone(1900 + Math.random()*500, .05, 'sine', .03, 0, dest, .5)); // dripping tap\n      } else if (loc === 'corridor'){ bed(brown,'lowpass',300,.07); hum(100,.008); }\n      else if (loc === 'bus'){ bed(brown,'lowpass',170,.16); hum(62,.014); }                   // the engine, and the road under the floor\n      else if (loc === 'taxi'){ bed(brown,'lowpass',210,.1); hum(84,.006); }\n      else if (loc === 'street' || loc === 'shops' || WEST.has(loc)){\n        bed(brown,'lowpass',700,.14);\n        if (loc === 'shops') loop(20000, 0, () => { if (Math.floor(NOW()/20000) % 2) for (let i=0;i<6;i++) tone(1800,.03,'square',.012,i*.5,dest); });   // the crossing beeps on green\n        loop(5000, 6000, () => noise(2.6,{vol:.16,type:'lowpass',freq:250,sweep:[1500,250],buf:brown,dest}));\n        loop(25000, 30000, () => { tone(420,.22,'square',.02,0,dest); tone(530,.22,'square',.02,.03,dest); });\n      } else if (loc === 'park'){\n        bed(brown,'lowpass',420,.07);\n        loop(1800, 3500, () => { const f = 2400 + Math.random()*1400, k2 = 2 + Math.floor(Math.random()*3);\n          for (let i=0;i<k2;i++) tone(f*(1+i*.06), .07, 'sine', .035, i*.11, dest, 1.3); });\n        loop(15000, 20000, () => { tone(330,.12,'sawtooth',.025,0,dest,.7); tone(330,.12,'sawtooth',.025,.2,dest,.7); });\n      } else if (loc === 'market'){\n        bed(brown,'bandpass',600,.2);\n        loop(2500, 4000, () => { const f = 300 + Math.random()*200; for (let i=0;i<3;i++) tone(f*(1+(i%2)*.25), .14, 'square', .02, i*.16, dest, .9); });   // vendors calling prices\n        loop(9000, 9000, () => noise(1.8,{vol:.1,type:'lowpass',freq:250,sweep:[1200,250],buf:brown,dest}));\n      } else if (loc === 'apt2'){\n        bed(brown,'lowpass',260,.05); hum(110,.003);                                                     // a lived-in flat, the fish tank's pump\n        loop(1500, 2500, () => tone(900 + Math.random()*500, .04, 'sine', .015, 0, dest, 1.6));          // bubbles\n      } else if (loc === 'hall1'){ bed(brown,'lowpass',300,.07); hum(100,.008);\n      } else if (loc === 'plaza'){\n        bed(brown,'lowpass',460,.08);                                                                    // the park next door, a little traffic far off\n        loop(2600, 4500, () => { const f = 2300 + Math.random()*1300; tone(f, .07, 'sine', .03, 0, dest, 1.3); });\n      } else if (loc === 'arena'){\n        bed(brown,'lowpass',180,.06); hum(60,.01);                                                       // a big brick room and its old pipes\n        loop(9000, 14000, () => noise(.6,{vol:.03,type:'lowpass',freq:300,dest}));                       // the pipes knock now and then\n      } else if (loc === 'campus'){\n        bed(brown,'bandpass',520,.09);                                                                    // students talking across the courtyard\n        loop(1800, 3500, () => { const f = 2400 + Math.random()*1400; tone(f, .07, 'sine', .03, 0, dest, 1.3); });\n      } else if (loc === 'classroom'){\n        bed(brown,'lowpass',340,.05); hum(100,.004);                                                      // a quiet room and its lights\n        loop(7000, 12000, () => noise(.05,{vol:.03,type:'bandpass',freq:1800,q:3,dest}));                  // a pen on a desk\n      } else if (loc === 'store'){\n        bed(brown,'lowpass',500,.07); hum(120,.006);\n        loop(5000, 7000, () => tone(1650, .08, 'square', .02, 0, dest));                                     // the checkout scanner\n      } else if (loc === 'gym'){\n        bed(brown,'lowpass',380,.08); hum(52,.012);                                                      // treadmill motors\n        loop(110, 130, () => { if (Math.random()<.75) noise(.09,{vol: extra==='walker' ? .1 : .05, type:'bandpass', freq:500+Math.random()*900, q:4, dest}); });   // the TV, sound on\n        loop(9000, 12000, () => { tone(170,.08,'square',.03,0,dest); noise(.15,{vol:.05,type:'lowpass',freq:900,dest}); });                            // a dumbbell clanks\n        if (extra === 'walker') loop(420, 0, () => noise(.03,{vol:.035,type:'lowpass',freq:300,dest}));                                                // his steps on the belt\n      } else if (loc === 'bar'){\n        bed(brown,'bandpass',420, extra === 'lesson' ? .05 : .15);                                        // the crowd\n        loop(4000, 6000, () => tone(2600 + Math.random()*700, .25, 'sine', .018, 0, dest));                // glasses\n        if (extra !== 'lesson' && !streamStart(a, 'bar')) music(a);                                        // no music during the improv class\n      } else if (loc === 'cafe'){\n        bed(brown,'bandpass',500,.25); streamStart(a, 'cafe');\n        loop(2500, 5000, () => tone(2300 + Math.random()*900, .3, 'sine', .02, 0, dest));\n        loop(20000, 20000, () => noise(2,{vol:.04,type:'highpass',freq:3000,dest}));\n      }\n      if ((wx === 'rain' || wx === 'storm') && loc !== 'static' && loc !== 'offscreen') bed(white, 'bandpass', 2600, OUTSIDE.has(loc) ? (wx==='storm' ? .13 : .09) : .025);\n      if (wx === 'storm' && loc !== 'static' && loc !== 'offscreen'){   // thunder a few seconds after each flash\n        const out = OUTSIDE.has(loc) ? 1 : .45;\n        const roll = () => { if (!a.alive) return; const n = NOW(), slot = Math.floor(n/30000) + 1, seed = (slot*9301+49297)%233280/233280,\n          at = slot*30000 + Math.floor(seed*22000) + 2500 + (slot%3)*900, wait = at - n;\n          setTimeout(() => { if (!a.alive) return; noise(3.2,{vol:.22*out,type:'lowpass',freq:160,sweep:[420,90],buf:brown,dest}); noise(1.4,{vol:.12*out,type:'lowpass',freq:300,when:.15,buf:brown,dest}); roll(); }, Math.max(200, wait)); };\n        roll();\n      }\n      if (extra === 'shower') bed(white, 'bandpass', 3200, .05);\n      if (extra === 'toilet') setTimeout(() => { if (a.alive){ noise(2.4,{vol:.12,type:'lowpass',freq:500,sweep:[1800,300],dest}); noise(1.2,{vol:.05,type:'highpass',freq:2500,when:1.4,dest}); } }, 6000 + Math.random()*8000);\n      if (extra === 'tv') loop(110, 130, () => { if (Math.random()<.7) noise(.09,{vol:.07,type:'bandpass',freq:500+Math.random()*900,q:4,dest}); });\n      if (extra === 'radio' && !streamStart(a)) music(a);\n    }\n    // an endless little chiptune for the radio, a new tune each time it turns on\n    function music(a){\n      const lp = ac.createBiquadFilter(); lp.type = 'lowpass'; lp.frequency.value = 2600;\n      const duckG = ac.createGain(); lp.connect(duckG).connect(a.gain); a.duck = duckG;   // the DJ talks over the music\n      const scale = [0,2,4,7,9,12,14,16]; let root = 220 * Math.pow(2, Math.floor(Math.random()*6)/12);\n      const pick = () => Math.random() < .75 ? scale[Math.floor(Math.random()*scale.length)] : null;\n      const melody = Array.from({length:16}, pick), bass = [0,0,-5,-3];\n      let dt = 60/(96 + Math.random()*30)/2, step = 0, next = ac.currentTime + .1;\n      a.reseed = () => { root = 196 * Math.pow(2, Math.floor(Math.random()*8)/12); dt = 60/(88 + Math.random()*44)/2; melody.forEach((v,i) => melody[i] = pick()); step = 0;\n        [660, 880, 1320].forEach((f,i) => tone(f, i===2 ? .3 : .12, 'square', .03, i*.13, a.gain)); };   // station jingle\n      const tick = () => {\n        if (!a.alive) return;\n        if (next < ac.currentTime) next = ac.currentTime + .05;\n        while (next < ac.currentTime + .3){\n          const st = step % 16, w = next - ac.currentTime;\n          if (melody[st] !== null) tone(root*Math.pow(2, melody[st]/12), dt*.9, 'square', .022, w, lp);\n          if (st % 4 === 0) tone(root/2*Math.pow(2, bass[Math.floor(step/16)%4]/12), dt*1.8, 'triangle', .05, w, lp);\n          if (st % 2 === 1) noise(.03,{vol:.012,type:'highpass',freq:6000,when:w,dest:lp});\n          step++; next += dt;\n          if (step % 64 === 0) melody.forEach((v,i) => { if (Math.random() < .3) melody[i] = pick(); });\n        }\n        setTimeout(tick, 100);\n      };\n      tick();\n    }\n\n    // small character sounds (typing, a page, a creak, steps, a clink...), played now and then by the scheduler below\n    function sfx(kind){\n      if (!on() || !ac) return;\n      const r = Math.random;\n      switch(kind){\n        case 'type': { let w = 0; for (let i = 0; i < 7 + Math.floor(r()*6); i++){ noise(.012,{vol:.045,type:'highpass',freq:3200+r()*800,when:w}); w += .06 + r()*.09; } if (r() < .5) noise(.03,{vol:.05,type:'lowpass',freq:500,when:w+.05}); break; }\n        case 'mouse': tone(1900,.01,'square',.03); tone(1900,.01,'square',.03,.13); break;\n        case 'chips': for (let i = 0; i < 3 + Math.floor(r()*3); i++) tone(2600 + r()*900, .025, 'triangle', .03, i*.05 + r()*.02); break;   // chips on felt\n        case 'shuffle': { let w = 0; for (let i = 0; i < 18; i++){ noise(.02,{vol:.04,type:'highpass',freq:2500+r()*1500,when:w}); w += .025 + r()*.02; } break; }\n        case 'card': noise(.03,{vol:.04,type:'bandpass',freq:3200,q:2}); break;\n        case 'applause': case 'ovation': { const long = kind === 'ovation' ? 9 : 5, n = kind === 'ovation' ? 260 : 140;   // many hands, a few whistles and a woo\n          for (let i = 0; i < n; i++){ const w = Math.pow(r(), .7) * long; noise(.018 + r()*.02, {vol: (.03 + r()*.05) * (1 - w / long * .7), type:'bandpass', freq: 1200 + r()*2200, q: 1.2, when: w}); }\n          for (let i = 0; i < (kind === 'ovation' ? 4 : 2); i++){ const w = r() * long * .6; tone(1900 + r()*500, .35, 'sine', .025, w, out, 1.35); }\n          noise(1.2, {vol:.05, type:'bandpass', freq:420, q:.9, when: .2, buf: brown}); break; }\n        case 'murmur': noise(3.2, {vol:.04, type:'bandpass', freq: 380 + r()*250, q: .8, buf: brown}); noise(2.5, {vol:.015, type:'bandpass', freq: 900 + r()*400, q: 3, when: .4}); break;   // a room full of people talking\n        case 'sticks': for (let i = 0; i < 4; i++) tone(2600, .025, 'square', .05, i * .5); break;   // one, two, three, four\n        case 'chair': tone(130 + r()*40,.35,'sawtooth',.018,0,out,1.5); break;\n        case 'game':  [880,1175,1568].forEach((f,i) => tone(f*(r()<.5?1:.75),.06,'square',.028,i*.08)); break;\n        case 'page':  noise(.18,{vol:.05,type:'highpass',freq:2500,sweep:[5000,1500]}); break;\n        case 'remote': tone(2400,.02,'square',.03); noise(.15,{vol:.04,type:'bandpass',freq:1200,when:.1}); break;\n        case 'sizzle': noise(1.6,{vol:.04,type:'highpass',freq:4000}); break;\n        case 'clink': tone(2600,.25,'sine',.04); tone(3150,.2,'sine',.03,.05); break;\n        case 'crunch': for (let i = 0; i < 3; i++) noise(.05,{vol:.06,type:'lowpass',freq:900,when:i*.16}); break;\n        case 'sip':   noise(.3,{vol:.045,type:'bandpass',freq:700,q:3,sweep:[1200,500]}); break;\n        case 'steps': for (let i = 0; i < 4; i++) noise(.05,{vol:.08,type:'lowpass',freq:300,when:i*.42}); break;\n        case 'phone': tone(150,.18,'square',.03); tone(150,.18,'square',.03,.3); break;\n        case 'snore': noise(1.4,{vol:.05,type:'lowpass',freq:250,sweep:[500,180],buf:brown}); break;\n        case 'breath': noise(.4,{vol:.03,type:'bandpass',freq:900,q:1.5}); noise(.4,{vol:.025,type:'bandpass',freq:700,q:1.5,when:.55}); break;\n        case 'bark': bark(); break;\n        case 'keys': { // a few bars on the little keyboard: a wandering pentatonic tune over a slow bass, now and then a wrong note\n          const sc = [262,294,330,392,440,523,587,659]; let i = 2 + Math.floor(r()*3), w = 0;\n          for (let n = 0; n < 16; n++){ i = Math.max(0, Math.min(sc.length - 1, i + Math.floor(r()*5) - 2)); const d = r() < .25 ? .5 : .28;\n            tone(sc[i] * (r() < .06 ? 1.06 : 1), d * .9, 'triangle', .028, w); if (n % 4 === 0) tone(sc[i % 3] / 2, .9, 'sine', .022, w); w += d; }\n          break; }\n        case 'sweep': for (let i = 0; i < 4; i++) noise(.32,{vol:.05,type:'bandpass',freq:2600,q:.8,sweep:[3400,1800],when:i*.62}); break;\n        case 'wipe':  for (let i = 0; i < 5; i++) noise(.16,{vol:.035,type:'bandpass',freq:1800,q:1.2,when:i*.3}); break;\n        case 'splash': noise(.6,{vol:.05,type:'bandpass',freq:900,q:.6,sweep:[1500,600]}); tone(2600,.2,'sine',.025,.5); break;\n        case 'ping': tone(1320,.07,'sine',.05); tone(1760,.1,'sine',.04,.08); break;\n        case 'truck': noise(3.2,{vol:.07,type:'lowpass',freq:220,sweep:[320,160],buf:brown}); for (let i = 0; i < 3; i++) tone(95,.12,'square',.03,.7 + i*.8); noise(.12,{vol:.05,type:'bandpass',freq:1400,when:2.4}); break;\n        case 'megaphone': [392,392,466,349].forEach((f,i) => { tone(f,.32,'sawtooth',.016,i*.38); tone(f*1.01,.32,'square',.01,i*.38); }); break;\n        case 'piano': [262,294,330,262,294,330,349,330].forEach((f,i) => tone(f*(i === 6 && r() < .5 ? .94 : 1),.42,'triangle',.022,i*.46)); break;\n        case 'kids': for (let i = 0; i < 6; i++){ noise(.28,{vol:.018,type:'bandpass',freq:1400+r()*1500,q:4,when:i*.3}); tone(620+r()*600,.14,'triangle',.008,i*.3+.05,out,1.3); } break;\n        case 'gas': for (let i = 0; i < 3; i++){ tone(1050+i*60,.3,'sine',.018,i*.5); noise(.05,{vol:.04,type:'bandpass',freq:900,when:i*.5}); } break;\n        case 'gameshow': [523,659,784,1047].forEach((f,i) => tone(f,.12,'square',.012,i*.12)); noise(.9,{vol:.012,type:'bandpass',freq:1800,q:.7,when:.55}); break;\n      }\n    }\n    function bark(){\n      if (!on()) return;\n      noise(.09,{vol:.12,type:'bandpass',freq:650,q:2}); noise(.08,{vol:.1,type:'bandpass',freq:720,q:2,when:.16});\n      tone(420,.07,'square',.025,0,out,.6); tone(460,.06,'square',.02,.16,out,.6);\n    }\n    const btn = $('snd');\n    function setMode(m){\n      if (!init()){ btn.textContent = 'NO AUDIO'; return; }\n      if (ac.state === 'suspended') ac.resume();\n      mode = m; btn.textContent = LABELS[mode]; blocked = false;\n      if (mode === 'voices' && 'speechSynthesis' in window) try { const u = new SpeechSynthesisUtterance(' '); u.volume = 0; speechSynthesis.speak(u); } catch(e){}   // a tap is what allows speech: use it now\n      try { sessionStorage.setItem('ishaiSound', mode); } catch(e){}\n      if (mode !== 'voices' && 'speechSynthesis' in window) speechSynthesis.cancel();\n      ambKey = ''; setAmbience(wanted);\n    }\n    btn.onclick = (e) => { e.stopPropagation(); setMode(blocked ? 'voices' : MODES[(MODES.indexOf(mode)+1) % MODES.length]); };\n    // after an automatic update the browser mutes the page; the first tap anywhere brings the sound back\n    let saved = 'off'; try { saved = sessionStorage.getItem('ishaiSound') || 'off'; } catch(e){}\n    if (saved !== 'off'){\n      btn.textContent = 'SOUND: TAP ANYWHERE';\n      const resume = () => { document.removeEventListener('pointerdown', resume, true); document.removeEventListener('keydown', resume, true); if (mode === 'off') setMode(saved); };\n      document.addEventListener('pointerdown', resume, true); document.addEventListener('keydown', resume, true);\n    }\n    function bell(){ if (!on()) return; tone(660, .3, 'sine', .06); tone(523, .45, 'sine', .06, .32); }\n    function ring(){ if (!on()) return; for (let k = 0; k < 2; k++) for (let i = 0; i < 8; i++){ tone(880, .05, 'square', .03, k * .9 + i * .06); tone(1100, .05, 'square', .02, k * .9 + i * .06 + .03); } }\n    function duck(down){ djDown = !!down; }\n    // music volume: a quick fade down while anyone talks (characters, hosts, callers, the DJ), back up after.\n    // Phones that don't allow volume control (iOS) pause the stream instead and pick it up again.\n    setInterval(() => {\n      const talk = NOW() - TALK_AT < 700 || saying > 0;\n      if (amb && amb.duck && ac) amb.duck.gain.setTargetAtTime(djDown ? .15 : talk ? .35 : 1, ac.currentTime, .1);\n      const el = amb && amb.audio; if (!el) return;\n      if (volOk === null){ const v = el.volume; el.volume = v > .5 ? v - .05 : v + .05; volOk = Math.abs(el.volume - v) > .01; el.volume = v; }\n      const target = radioVol * placeVol * (djDown ? .22 : 1) * (talk ? .3 : 1);\n      if (volOk){ const d = target - el.volume; el.volume = Math.max(0, Math.min(1, Math.abs(d) <= .04 ? target : el.volume + Math.sign(d) * .04)); }\n      else if (talk && !el.paused){ el.pause(); el.dataset.held = '1'; }\n      else if (!talk && el.paused && el.dataset.held === '1' && NOW() - TALK_AT > 1500){ el.dataset.held = ''; el.play().catch(()=>{}); }\n    }, 50);\n    function newSong(){ if (amb && amb.reseed) amb.reseed(); }\n    const speaking = () => mode === 'voices';\n    // anyone speaking right now (a voice still talking, or one queued)? sound effects wait for it\n    const busy = () => saying > 0 || ('speechSynthesis' in window && (speechSynthesis.speaking || speechSynthesis.pending));\n    function hush(){ try { if ('speechSynthesis' in window && (speechSynthesis.speaking || speechSynthesis.pending)) speechSynthesis.cancel(); } catch(e){} }   // a slow voice never runs into the next scheduled line\n    // the pop-out window plays the page's sound, which keeps it running in the background; a faint tone holds the track open when nothing else plays\n    function popAudio(){\n      if (!init()) return null; try { ac.resume(); } catch(e){}\n      const dest = ac.createMediaStreamDestination(), o = ac.createOscillator(), keep = ac.createGain();\n      o.frequency.value = 40; keep.gain.value = .002; o.connect(keep); keep.connect(dest); o.start();\n      out.connect(dest); out.disconnect(ac.destination);\n      return {stream: dest.stream, stop(){ try { o.stop(); out.disconnect(dest); out.connect(ac.destination); } catch(e){} }};\n    }\n    return { isOn: () => on(), voiceInfo: () => `${voiceState} · ${voices.length} English voices`, blip, key, say, hush, popAudio, setAmbience, bark, duck, newSong, speaking, streaming, restartAmb, ring, bell, sfx, busy };\n  })();\n  function ambienceKey(){\n    if (actor.switching) return 'static||';\n    const settled = !actor.travelling && !actor.hidden;\n    let extra = settled && actor.loc==='apartment' ? (actor.action==='watching' ? 'tv' : actor.action==='listening' ? 'radio' : '') : '';\n    if (settled && actor.loc==='gym' && actor.action==='exercising') extra = 'walker';\n    if (actor.loc==='bar' && actor.action==='improv') extra = 'lesson';\n    if (actor.loc==='bathroom' && actor.hidden && BATH.has(actor.action)) extra = actor.action==='showering' ? 'shower' : 'toilet';\n    return `${actor.loc}|${extra}|${isNight(hourNow()) ? 'night' : 'day'}|${stormy() ? 'storm' : rainy() ? 'rain' : ''}`;\n  }\n\n  // ================= terminal =================\n  const term = $('term');\n  const shown = new Set(), held = new Map();\n  const queue = []; let typing = false;\n\n  // the two show hosts\n  const HOSTS = {\n    zohar:{name:'ZOHAR', color:'#ff9ad0', look:{hair:'long',hairColor:'red',skin:'fair',shirt:'pink',pants:'black',extras:['earring']}},\n    oren:{name:'OREN', color:'#9fd0ff', look:{hair:'short',hairColor:'gray',skin:'tan',shirt:'navy',pants:'gray',extras:['glasses','beard']}}\n  };\n  // every character's own colour: the bubble's outline and name tab use it as is; dark backgrounds (chat, cast) use a lighter tint\n  const INK = {ishai:'#24998a', noa:'#d0479a', levi:'#8a4fd0', avi:'#e07b1f', dana:'#c99a12', tomer:'#2f6fd6', gadi:'#5f7088', michal:'#d23c3c',\n    sivan:'#2f9e4a', zelig:'#8a6a3a', kobi:'#a8306a', lior:'#3f8fae', yael:'#e0603a', sasson:'#5a5ad0', hagit:'#4f8a8b', boaz:'#7d8f2a', ronit:'#ff6f61', moti:'#c47b9a', yossi:'#9acd32', radio:'#c9a227', tv:'#3f8fd0'};\n  const INK_MORE = ['#b5523b','#2c8c6e','#7a5fc0','#c07a1a','#3b7bc2','#a83f8f','#5c8a2a','#c04848'];   // anyone new: picked by name, always the same\n  const inkOf = id => INK[id] || (/^student\\d$/.test(id) ? '#7d857a' : INK_MORE[strHash(id) % INK_MORE.length]);\n  const inkText = hex => { const n = parseInt(hex.slice(1), 16), l = .299 * (n >> 16) + .587 * ((n >> 8) & 255) + .114 * (n & 255); return l > 150 ? '#151515' : '#ffffff'; };\n  function speaker(id){ const s = speakerBase(id); if (!HOSTS[id]){ s.ink = inkOf(id); if (id !== 'radio' && id !== 'tv') s.color = tint(s.ink, .45); } else s.ink = HOSTS[id].color; return s; }\n  function speakerBase(id){\n    if (HOSTS[id]) return {name:HOSTS[id].name, color:HOSTS[id].color};\n    if (id==='radio') return boolifyOn() ? {name:'BOOLIFY', color:'#ff7ad9'} : {name:'RADIO HERZL 88.2', color:'#ffd36a'};\n    if (id==='tv') return {name: CUR_MEDIA === '8bittv' ? '8BITTV' : CUR_MEDIA === 'nesflicks' ? 'NESFLICKS' : CUR_MEDIA === 'rgbeat' ? 'RGBEAT' : 'CHANNEL 9', color:'#9fd0ff'};\n    if (id==='ishai') return {name:'ISHAI', color:tint(CLOTH.teal,.45)};\n    if (/^student\\d$/.test(id)) return {name:'STUDENT', color:'#b8c4b0'};\n    if (EXTRA_SPK[id]) return {name: EXTRA_SPK[id].toUpperCase(), color: tint(CLOTH.gray,.45)};   // a band member on stage\n    const c = CAST[id]; return {name:(c?c.name:id).toUpperCase(), color: tint(CLOTH[c?.look?.shirt]||CLOTH.gray,.45)};\n  }\n  const charDelay = ch => 28 + (ch===','?120:ch==='.'?220:0);\n  // budget.ms = how far into this moment we already are (a viewer tuning in late joins mid-sentence)\n  function typeInto(el, full, animate, onChar, budget){\n    if (!animate){ el.textContent = full; term.scrollTop = term.scrollHeight; return Promise.resolve(); }\n    let i = 0; const at = budget && budget.at;     // at = when this line started: the typing stays on that schedule\n    if (at) i = charsAt(full, NOW() - at);\n    while (budget && budget.ms > 0 && i < full.length){ budget.ms -= charDelay(full[i]); i++; }\n    if (i >= full.length){ el.textContent = full; term.scrollTop = term.scrollHeight; return Promise.resolve(); }\n    return new Promise(res=>{\n      const step=()=>{ i = Math.min(full.length, Math.max(i + 1, at ? charsAt(full, NOW() - at) : 0)); el.textContent = full.slice(0,i); term.scrollTop = term.scrollHeight; if (onChar) onChar(full[i-1]);\n        if (i<full.length) setTimeout(step, charDelay(full[i-1])); else res(); };\n      step(); });\n  }\n  function newLine(cls){\n    term.querySelectorAll('.cursor').forEach(c=>c.remove());\n    term.querySelectorAll('.line').forEach(l=>l.classList.add('old'));\n    const p = document.createElement('p'); p.className = 'line ' + (cls||''); term.appendChild(p);\n    while (term.querySelectorAll('.line').length > 80) term.removeChild(term.querySelector('.line'));\n    return p;\n  }\n  async function addLine(ev, animate){\n    shown.add(ev.id);\n    const p = newLine();\n    const ts = document.createElement('span'); ts.className='ts'; ts.textContent = `[${fmtHM.format(new Date(ev.t))}] `;\n    const tx = document.createElement('span'); const cur = document.createElement('span'); cur.className='cursor';\n    p.append(ts, tx, cur);\n    if (ev.src){ const sr = document.createElement('div'); sr.style.cssText = 'font-size:.75em;opacity:.55;margin-left:1.2em'; sr.textContent = 'written by: ' + ev.src; p.appendChild(sr); }\n    const budget = {ms: ev._late || 0};\n    const fresh = () => budget.ms <= 0; // only speak lines the viewer gets from the start\n    await Promise.all([animate && fresh() ? Sound.say('narrator', ev.text) : null, typeInto(tx, '> ' + ev.text, animate, ch=>Sound.key(ch), budget)]);\n    for (const l of (ev.lines||[])){\n      const sp = speaker(l.who), q = newLine('say');\n      const nm = document.createElement('span'); nm.style.color = sp.color; nm.textContent = sp.name + ': ';\n      const tx2 = document.createElement('span'); tx2.style.color = sp.color; const cur2 = document.createElement('span'); cur2.className='cursor';\n      q.append(nm, tx2, cur2);\n      await Promise.all([animate && fresh() ? Sound.say(l.who, l.say) : null, typeInto(tx2, '\"' + l.say + '\"', animate, ch=>Sound.blip(l.who, ch), budget)]);\n    }\n  }\n  async function pump(){\n    if (typing) return; typing = true;\n    while (queue.length){\n      const ev = queue.shift(); if (ev.unlocks) UNLOCKED.add(ev.unlocks);\n      if (showOn && SHOW_AUTO && SHOW_STOP && ((ev.lines||[]).length || ev.with || ev.location !== actor.loc)) SHOW_STOP();   // something happens: back to live\n      // several moments became due at once (phone woke up, tab came back): skip the silent ones in between, so he doesn't hop in and out of bed\n      if (queue.length && !(ev.lines || []).length){ shown.add(ev.id); if (DEV) addLine(ev, false); continue; }\n      const entry = TL.get(ev.id), start = startOf(ev); ev._late = Math.max(0, NOW() - start);\n      // already over with more waiting (tab came back): no walking through old moments; well into this one: be where he is by now\n      NEXT_RIDE = ev.ride || null; CUR_MEDIA = ev.media || null;\n      if (!forceLoc && !ev._joined && !(queue.length && entry && NOW() >= entry.end)) setState(ev.location||'apartment', ev.action, ev._late > 20000, ev.with||null);\n      actor.hint = homeHint(ev.text); actor.hintUntil = entry ? entry.end : NOW() + 360000;\n      actor.delivery = ev.delivery && ev._late < 35000 ? {at: start} : null;   // an ateBite courier at the door\n      enterScene(ev.location, ev.with);\n      if (DEV){ addTalk(ev, true); await addLine(ev,true); }   // talk + hosts play in their own time (hosts wait for the picture)\n      else { shown.add(ev.id);\n        if (PREVIEW) for (let w = 0; w < 40 && (actor.pending || actor.travelling || actor.switching || actor.ride); w++) await new Promise(r => setTimeout(r, 500)); // preview: talk once they have arrived\n        if (PREVIEW && entry){ const d = entry.end - entry.start; entry.start = NOW(); entry.end = entry.start + d; }\n        await addTalk(ev, true); }\n    }\n    typing = false;\n  }\n  // events with a future timestamp (broadcast delay) are held until their time comes\n  // the schedule: everything below is worked out from the moments alone, so every page gets the same times\n  const TL = new Map(); let tlLast = null;       // moment id -> {ev, start, end, plan}, in order\n  const typeMs = full => [...full].reduce((n, ch) => n + charDelay(ch), 0);\n  const charsAt = (full, ms) => { let i = 0; while (ms > 0 && i < full.length){ ms -= charDelay(full[i]); i++; } return i; };\n  // each line gets the same slot on every device: long enough for the typing and for a voice to say it\n  const lineMs = say => Math.max(typeMs('\"' + say + '\"'), 500 + say.length * 70);\n  const WAITS = new Set();    // the sandbox can cut waits short\n  const untilT = at => { const ms = at - NOW(); if (ms <= 0) return Promise.resolve(); return new Promise(r => { const f = () => { WAITS.delete(f); clearTimeout(id); r(); }, id = setTimeout(f, ms); WAITS.add(f); }); };\n  function talkPlan(ev, prevLoc){\n    const lines = ev.lines || [], hosts = ev.commentary || [], gap = PREVIEW ? 600 : convoGap(lines), plan = [];\n    // arriving by bus or taxi: the talk waits until he is there\n    const r = prevLoc && !PREVIEW && prevLoc !== (ev.location || 'apartment') ? route(prevLoc, ev.location || 'apartment') : [], onBoard = r.some(x => VEH.has(x)) && !VEH.has(prevLoc) && !VEH.has(ev.location);\n    const lead = onBoard ? RIDE_LEAD + RIDE_MS + RIDE_LAND : 0; let t = lead;\n    lines.forEach((l, i) => { if (i) t += linePause(lines[i-1].say) + gap; const ms = lineMs(l.say); plan.push({at: t, ms, l, i}); t += ms; });\n    if (hosts.length){   // the hosts react to what viewers can SEE: after Ishai has got there, then a short beat\n      t = Math.max(t + (lines.length ? 1200 : 0), lead + (prevLoc && prevLoc !== (ev.location || 'apartment') ? 17500 : 5000));\n      hosts.forEach((c, i) => { if (i) t += linePause(hosts[i-1].say); const ms = lineMs(c.say); plan.push({at: t, ms, l: c, i, host: true}); t += ms; });\n    }\n    return {plan, ms: t, ride: onBoard ? r : null};\n  }\n  function schedule(events){\n    [...events].sort((a,b)=>a.t-b.t).forEach(e => {\n      if (TL.has(e.id)) return;\n      const p = talkPlan(e, tlLast && (tlLast.ev.location || 'apartment')), start = Math.max(e.t, tlLast ? tlLast.end : 0);   // a long talk finishes before the next moment starts\n      tlLast = {ev: e, start, end: start + p.ms, plan: p.plan, ride: p.ride}; TL.set(e.id, tlLast);\n    });\n    while (TL.size > 60) TL.delete(TL.keys().next().value);\n  }\n  const startOf = e => TL.has(e.id) ? TL.get(e.id).start : e.t;\n  function release(){\n    const now = NOW();\n    [...held.values()].filter(e=>startOf(e)<=now).sort((a,b)=>startOf(a)-startOf(b)).forEach(e=>{ held.delete(e.id); queue.push(e); });\n    pump();\n  }\n  setInterval(release, 1000);   // the picture loop does this every frame; this keeps background tabs going\n  function ingest(events, firstLoad){\n    TUNING = false;\n    const now = NOW();\n    if (firstLoad && !params.has('sleptMin')){ // when did this sleep start? (the run of sleeping moments at the end)\n      const past = events.filter(e => e.t <= now).sort((a,b) => a.t - b.t); let i = past.length - 1, since = null;\n      while (i >= 0 && past[i].action === 'sleeping'){ since = past[i].t; i--; }\n      if (since) SLEEP_SINCE = since; }\n    schedule(events);\n    const fresh = events.filter(e=>!shown.has(e.id) && !held.has(e.id)).sort((a,b)=>a.t-b.t);\n    const due = fresh.filter(e=>startOf(e)<=now);\n    fresh.filter(e=>startOf(e)>now).forEach(e=>held.set(e.id,e));\n    due.forEach(e=>{ if (e.unlocks && firstLoad) UNLOCKED.add(e.unlocks); });\n    if (firstLoad && due.length){\n      const newest = due.pop();\n      // conversation history (older lines than the moment we tune into)\n      const nk = newest.id + ':';\n      sceneKey = keyOf(newest.location, newest.with);\n      // the current scene started where the place or the company last changed\n      let start = due.length; while (start > 0 && keyOf(due[start-1].location, due[start-1].with) === sceneKey) start--;\n      const sceneStart = start < due.length ? due[start].t : newest.t;\n      (TALK_HISTORY||[]).filter(m => m.t <= now && m.t >= sceneStart && !m.host && m.loc === newest.location && (m.w === undefined || (m.w||'') === (newest.with||'')) && !String(m.id).startsWith(nk)).forEach(m => addMsg(m, false));\n      (TALK_HISTORY||[]).filter(m => m.host && m.t <= now && !String(m.id).startsWith(nk)).forEach(m => addMsg(m, false)); // the booth keeps the hosts' recent lines\n      due.forEach((e, i)=>{ if (DEV) addLine(e,false); else shown.add(e.id); if (i >= start) addTalk(e,false); else (e.lines||[]).forEach((l,k)=>talkShown.add(e.id+':'+k)); });\n      if (!forceLoc) joinMoment(TL.get(newest.id), stepTo(NOW()));\n      // tune in live: join the newest moment as far into it as real time says\n      queue.push(newest); pump();\n    } else { due.forEach(e=>queue.push(e)); pump(); }\n  }\n\n  // ================= conversations =================\n  let DEV = false, TALK_HISTORY = [];\n  const talkEl = $('talk'), talkShown = new Set();\n  let lastScene = '';\n  const PLACE_NAME = {apartment:'APARTMENT 4', corridor:'2ND FLOOR HALL', street:'HERZL ST.', shops:'HERZL ST. SHOPS', west1:'HERZL ST. WEST', west2:'HERZL ST. WEST', west3:'HERZL ST. WEST', market:'SHUK SHALOM', campus:'TEL HERZL UNIVERSITY', classroom:'LECTURE ROOM', store:'EVERYTHING ELSE', bus:'LINE 88', taxi:'TAXI', gym:'HERZL GYM', bar:'THE BLACK CANDLE', park:'GAN HA-IR PARK', plaza:'THE PUMP HOUSE', arena:'PUMP HOUSE HALL', hall1:'1ST FLOOR HALL', apt2:'APARTMENT 2', cafe:'CAFE NAHAT', bathroom:'BATHROOM', offscreen:'OFF CAMERA'};\n  function faceCanvas(who){\n    const c = document.createElement('canvas'); c.width = 12; c.height = 12;\n    const prev = g; g = c.getContext('2d'); R(0,0,12,12,'#0b120b');\n    if (HOSTS[who]){ person(HOSTS[who].look, 1, 2, 0, {face:0, seed:999, legs:false});\n      R(2,1,8,1,'#222'); R(1,4,1,4,'#333'); R(10,4,1,4,'#333'); R(9,8,2,1,'#333'); R(8,8,1,1,'#c23b3b'); }\n    else if (who === 'ishai'){ head(1,2,{}); torso(1,2); }\n    else if (CAST[who] && CAST[who].look) person(CAST[who].look, 1, 2, 0, {face:0, seed:999, legs:false});\n    else { R(4,4,4,4,'#555'); }\n    g = prev; return c;\n  }\n  // the hosts' booth: each host keeps only their latest line\n  function boothInit(){\n    const h = document.createElement('div'); h.className = 'head'; h.textContent = '● ON AIR — ZOHAR & OREN'; $('booth').appendChild(h);\n    $('booth').addEventListener('scroll', e => { const b = e.currentTarget; boothFollow = b.scrollHeight - b.scrollTop - b.clientHeight < 24; }, {passive: true});\n  }\n  let boothFollow = true;   // the viewer scrolled up to read: leave them there until they come back to the bottom\n  const boothScroll = () => { const b = $('booth'); if (boothFollow) b.scrollTop = b.scrollHeight; };\n  function hostLine(m, animate, budget){\n    if (!talkShown.has(m.id) && HOSTS[m.who] && animate !== false) fsPush(m.who, m.say);\n    if (talkShown.has(m.id) || !HOSTS[m.who]) return Promise.resolve(); talkShown.add(m.id);\n    const booth = $('booth');\n    const card = document.createElement('div'); card.className = 'host';\n    const body = document.createElement('div');\n    const hn = document.createElement('div'); hn.className = 'hn'; hn.style.color = HOSTS[m.who].color; hn.textContent = HOSTS[m.who].name + ' ';\n    const tag = document.createElement('span'); tag.textContent = '· ' + fmtHM.format(new Date(m.t)); hn.appendChild(tag);\n    const line = document.createElement('div'); line.className = 'hl';\n    body.append(hn, line); card.append(faceCanvas(m.who), body); booth.appendChild(card);\n    card.classList.toggle('ad', /cooola|hummusprime|fluffnap|leaflove|sockwise|zenbrick|butcher is born|wee laddie|virgin scotch|atebite|kfar kofi|tahini tower|herzl hardware|yalla yoga|nesflicks|8bittv|boolify|rgbeat|picsell/i.test(m.say));\n    while (booth.querySelectorAll('.host').length > 10) booth.removeChild(booth.querySelector('.host'));\n    if (!animate){ line.textContent = m.say; boothScroll(); return Promise.resolve(); }\n    const full = m.say, b = budget || {at: NOW(), ms: 0}, into = Math.max(0, NOW() - b.at); let i = charsAt(full, into);\n    const quiet = studioOn || showOn;            // the studio recap is on: the booth goes on in text only\n    if (into < 800 && !quiet) Sound.say(m.who, m.say);     // tuned in later than the start of a line: read it, no voice\n    card.classList.add('live');\n    return new Promise(res => {\n      if (i >= full.length){ line.textContent = full; card.classList.remove('live'); boothScroll(); return res(); }\n      const step = () => { i = Math.min(full.length, Math.max(i + 1, charsAt(full, NOW() - b.at))); line.textContent = full.slice(0,i); boothScroll(); if (!quiet) Sound.blip(m.who, full[i-1]);\n        if (i < full.length) setTimeout(step, charDelay(full[i-1])); else { setTimeout(()=>card.classList.remove('live'), 1500); res(); } };\n      step();\n    });\n  }\n  function addMsg(m, animate, budget){\n    if (m.host) return hostLine(m, animate, budget);\n    if (talkShown.has(m.id)) return Promise.resolve(); talkShown.add(m.id);\n    if (m.t - (addMsg.lastT || m.t) > 30 * 60000) clearTalk();   // a new stretch of the day: start the conversation list afresh\n    addMsg.lastT = m.t;\n    if (animate) fsPush(m.who, m.say);\n    $('talkEmpty').hidden = true;\n    const scene = (m.loc||'') + '|' + fmtHM.format(new Date(m.t)).slice(0,2);\n    if (m.loc && m.loc !== lastScene.split('|')[0]){ const d = document.createElement('div'); d.className = 'scene'; d.textContent = `— ${PLACE_NAME[m.loc]||m.loc.toUpperCase()} · ${fmtHM.format(new Date(m.t))} —`; talkEl.appendChild(d); }\n    lastScene = scene;\n    const sp = speaker(m.who);\n    const isAd = m.host && /cooola|hummusprime|fluffnap|leaflove|sockwise|zenbrick|butcher is born|wee laddie|virgin scotch|atebite|kfar kofi|tahini tower|herzl hardware|yalla yoga|nesflicks|8bittv|boolify|rgbeat|picsell/i.test(m.say);\n    const row = document.createElement('div'); row.className = 'msg' + (m.host ? ' host' : '') + (isAd ? ' ad' : '');\n    const body = document.createElement('div');\n    const who = document.createElement('div'); who.className = 'who'; who.style.color = sp.color; who.textContent = sp.name + (m.via ? ' \\u00b7 ' + String(m.via).toUpperCase() : '');\n    const tm = document.createElement('small'); tm.textContent = fmtHM.format(new Date(m.t)); who.appendChild(tm);\n    const said = document.createElement('div'); said.className = 'said'; const cur = document.createElement('span'); cur.className = 'cursor';\n    body.append(who, said); row.append(faceCanvas(m.who), body);\n    talkEl.querySelectorAll('.cursor').forEach(x=>x.remove()); said.after(cur);\n    talkEl.appendChild(row);\n    while (talkEl.querySelectorAll('.msg').length > 120) talkEl.removeChild(talkEl.querySelector('.msg'));\n    const scroll = () => { talkEl.scrollTop = talkEl.scrollHeight; };\n    const full = m.host ? m.say : '\"' + m.say + '\"';\n    if (!animate){ said.textContent = full; cur.remove(); scroll(); return Promise.resolve(); }\n    const b = budget || {at: NOW(), ms: 0}, into = Math.max(0, NOW() - b.at); let i = charsAt(full, into);\n    if (into < 2000) Sound.say(m.who, m.say);    // tuned in well after the start of a line: read it, no voice\n    const hold = () => Math.max(2500, b.at + b.ms - NOW());\n    return new Promise(res => {\n      if (i >= full.length){ said.textContent = full; scroll(); if (!m.host && into < b.ms + 2500){ showSay(m.who, m.say); holdSay(b.at + b.ms + 2500 - NOW()); } return res(); }\n      if (!m.host) showSay(m.who, m.say.slice(0, Math.max(0, i-1)));\n      const step = () => { i = Math.min(full.length, Math.max(i + 1, charsAt(full, NOW() - b.at))); said.textContent = full.slice(0,i); scroll(); Sound.blip(m.who, full[i-1]); if (m.host) caption(sp, full.slice(0,i)); else showSay(m.who, m.say.slice(0, Math.max(0, i-1)));\n        if (i < full.length) setTimeout(step, charDelay(full[i-1])); else { if (!m.host){ showSay(m.who, m.say); holdSay(hold()); } res(); } };\n      step();\n    });\n  }\n  // natural pause between lines; also counted when a viewer tunes in mid-conversation\n  const linePause = say => 900 + Math.min(1600, say.length * 12);\n  // spread a long conversation over the whole moment (about 3 minutes), like real people talking\n  function convoGap(lines){\n    if (!lines || lines.length < 2) return 0;\n    const typing = lines.reduce((n, l) => n + lineMs(l.say) + linePause(l.say), 0);\n    return Math.max(0, Math.min(12000, (180000 - typing) / (lines.length - 1)));\n  }\n  let sceneKey = null;\n  const keyOf = (loc, w) => (loc || '') + '|' + (w || '');\n  function clearTalk(){\n    talkEl.querySelectorAll('.msg, .scene').forEach(n => n.remove());\n    lastScene = ''; $('talkEmpty').hidden = false;\n  }\n  function enterScene(loc, w){ const k = keyOf(loc, w); if (k !== sceneKey){ sceneKey = k; clearTalk(); } }\n  async function addTalk(ev, animate){\n    const entry = TL.get(ev.id);\n    if (!animate || !entry){    // history: everything at once\n      (ev.lines||[]).forEach((l, i) => addMsg({id: ev.id + ':' + i, t: ev.t, who: l.who, say: l.say, loc: ev.location}, false));\n      (ev.commentary||[]).forEach((c, i) => addMsg({id: ev.id + ':c' + i, t: ev.t, who: c.who, say: c.say, loc: ev.location, host: true}, false));\n      return;\n    }\n    for (let k = 0; k < entry.plan.length; k++){\n      const p = entry.plan[k], l = p.l;\n      if (p.host && k && !entry.plan[k-1].host) setSpeaking(null);\n      await untilT(entry.start + p.at); if (entry.dead) break;\n      const at = entry.start + p.at, past = NOW() >= at + p.ms;\n      if (!past && k) Sound.hush();\n      if (p.host){ await addMsg({id: ev.id + ':c' + p.i, t: ev.t, who: l.who, say: l.say, loc: ev.location, host: true}, true, {at, ms: p.ms}); await untilT(at + p.ms); continue; }\n      if (!past) setSpeaking(l.who);\n      const air = l.who==='radio' || l.who==='tv';   // a live line from the radio / TV the story reacts to\n      if (air){ MEDIA_UNTIL = at + 240000; if (l.who==='radio' && !past) Sound.duck(true); }\n      await addMsg({id: ev.id + ':' + p.i, t: ev.t, who: l.who, say: l.say, loc: ev.location, via: l.via}, true, {at, ms: p.ms});\n      await untilT(at + p.ms); if (entry.dead) break;\n      if (air && l.who==='radio' && !past) Sound.duck(false);\n    }\n    setSpeaking(null);\n  }\n  // the hosts' words also appear as live captions on the camera\n  let capTimer = 0;\n  function caption(){} // hosts are not shown on the camera\n\n\n  // ================= cast tab =================\n  let NOTES = '';\n  function setCast(list){\n    const next = {}; (list||[]).forEach(c=>{ next[c.id]=c; });\n    const changed = JSON.stringify(next) !== JSON.stringify(CAST);\n    CAST = next; if (changed && !$('castPanel').hidden) renderCast();\n    updateLabels();\n  }\n  function portrait(look, isIshai){\n    const c = document.createElement('canvas'); c.width = 14; c.height = 27;\n    const pc = c.getContext('2d'); const prev = g; g = pc;\n    R(0,0,14,27,'#0b120b');\n    if (isIshai){ head(2,4,{}); torso(2,4); armsDown(2,4); legs(2,4,0); }\n    else person(look, 2, 4, 0, {face:0, seed:999});\n    g = prev; return c;\n  }\n  const relWord = r => r<=-3?'HOSTILE':r<0?'ANNOYED':r===0?'NEUTRAL':r<3?'FRIENDLY':'CLOSE';\n  function relBar(r){ const n = Math.max(0,Math.min(10,(r||0)+5)); return '■'.repeat(n) + '□'.repeat(10-n); }\n  function card(look, name, color, meta, rel, mem, isIshai){\n    const d = document.createElement('div'); d.className='card';\n    d.appendChild(portrait(look, isIshai));\n    const b = document.createElement('div');\n    const nm = document.createElement('div'); nm.className='nm'; nm.style.color = color; nm.textContent = name;\n    const mt = document.createElement('div'); mt.className='meta'; mt.textContent = meta;\n    b.append(nm, mt);\n    if (rel!==null){ const rl = document.createElement('div'); rl.className='rel'; rl.textContent = `${relBar(rel)} ${relWord(rel)}`; b.appendChild(rl); }\n    const me = document.createElement('div'); me.className='mem'; me.textContent = mem; b.appendChild(me);\n    d.appendChild(b); return d;\n  }\n  const CAST_OPEN = new Set();   // closed rows the viewer opened (on-camera rows are always open)\n  function renderCast(){\n    const el = $('castPanel'); el.textContent = '';\n    // everyone, with whoever is on camera right now open at the top; the rest closed, in cast order\n    const visible = settledOnCamera();\n    const onCam = actor.loc !== 'offscreen' && !actor.switching;\n    const NOW_TAG = ' ● ON CAMERA NOW', rows = [];\n    const fold = (d, id, live) => {\n      if (live) { rows.push([0, d]); return; }\n      const open = CAST_OPEN.has(id);\n      d.classList.add('fold'); if (!open) d.classList.add('closed');\n      d.tabIndex = 0; d.setAttribute('role', 'button'); d.setAttribute('aria-expanded', String(open));\n      const flip = () => { CAST_OPEN.has(id) ? CAST_OPEN.delete(id) : CAST_OPEN.add(id); renderCast(); const again = el.querySelector(`[data-id=\"${id}\"]`); if (again) again.focus({preventScroll: true}); };\n      d.onclick = flip; d.onkeydown = e => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); flip(); } };\n      rows.push([1, d]);\n    };\n    const ishai = card(ISHAI_LOOK,'ISHAI',tint(CLOTH.teal,.45),'The subject. 31, freelance designer, apartment 4.' + (onCam ? NOW_TAG : ''),null,'STORY SO FAR: ' + (NOTES||'—'), true);\n    ishai.dataset.id = 'ishai'; fold(ishai, 'ishai', onCam);\n    if (UNLOCKED.has('dog')){\n      const c = document.createElement('canvas'); c.width = 14; c.height = 12; const pc = c.getContext('2d'); const prev = g; g = pc;\n      R(0,0,14,12,'#0b120b'); dogMap(DOG.sitA, 2, 3, false); g = prev;\n      const d = card(ISHAI_LOOK,'FALAFEL','#e8c48a',\"Ishai's dog. Scruffy, sandy, adopted from Avi's kiosk.\" + (onCam ? NOW_TAG : ''),null,'Eats everything. Trusts Ishai and Avi, and gets along with every Siberian Hascii he meets: Hasciis are his best friends after Ishai.', false);\n      d.replaceChild(c, d.firstChild); d.dataset.id = 'falafel'; fold(d, 'falafel', onCam);\n    }\n    Object.values(CAST).forEach(c=>{\n      const live = visible.has(c.id);\n      const d = card(c.look, c.name.toUpperCase(), tint(CLOTH[c.look?.shirt]||CLOTH.gray,.45),\n        `${c.role.charAt(0).toUpperCase()+c.role.slice(1)}. ${c.personality ? c.personality.charAt(0).toUpperCase()+c.personality.slice(1)+'.' : ''}${live ? NOW_TAG : ''}`,\n        c.relationship||0, 'MEMORY: ' + (c.memory||'—'));\n      d.dataset.id = c.id; fold(d, c.id, live);\n    });\n    if (!rows.some(r => r[0] === 0)){ const p = document.createElement('div'); p.className='meta'; p.textContent = 'Nobody on camera right now.'; el.appendChild(p); }\n    rows.sort((a, b) => a[0] - b[0]).forEach(r => el.appendChild(r[1]));\n  }\n  function settledOnCamera(){\n    const v = new Set();\n    if (actor.switching || actor.loc==='offscreen' || actor.loc==='bathroom') return v;\n    if (actor.with && !actor.travelling && actor.action!=='phoning') v.add(actor.with);\n    if (POST[actor.loc] && CAST[POST[actor.loc]]) v.add(POST[actor.loc]); // Avi at his kiosk, Dana behind the counter\n    return v;\n  }\n  // ================= Radio Herzl 88.2: an original station with a DJ =================\n  // Music (the chiptune) with a DJ every 80 s: real weather, real light headlines, Shabbat times, fictional ads and bands.\n  // Timed by the clock, so every viewer hears the same show. The DJ speaks in VOICES mode; the words always show in a bubble.\n  const RADIO = { seg:-1, spoken:-1, on:false, bad:new Set() };\n  const STATION_BLOCK = 20 * 60000; // a new station every 20 minutes (same for every viewer)\n  // the bar plays rock / alternative / light metal, the café pop and soft rock: fixed 24/7 stations first, the server's finds as backup\n  const PLACE_STATIONS = {\n    bar:  [{name:'Radio Paradise - Rock Mix', url:'https://stream.radioparadise.com/rock-128', tag:'rock'}],\n    cafe: [{name:'SomaFM - Left Coast 70s', url:'https://ice.somafm.com/seventies', tag:'soft rock'}, {name:'Radio Paradise - Mellow Mix', url:'https://stream.radioparadise.com/mellow-128', tag:'soft pop'}]\n  };\n  function radioPick(kind){\n    if (kind === 'bar' || kind === 'cafe') return [...PLACE_STATIONS[kind], ...((WORLD && WORLD[kind + 'Stations']) || [])].filter(s => !RADIO.bad.has(s.url))[0] || null;\n    const list = ((WORLD && WORLD.stations) || []).filter(s => !RADIO.bad.has(s.url)); if (!list.length) return null;\n    return list[Math.floor(hash(Math.floor(NOW() / STATION_BLOCK) * 3 + 7) * list.length)];\n  }\n  function radioFail(url){ RADIO.bad.add(url); if (Sound.streaming() !== null || RADIO.on) Sound.restartAmb(); }\n  const BANDS = [['The Basil Leaves','Morning on Herzl Street'],['Falafel Kings','Extra Tahini'],['Lady Hummus','Chickpea Heart'],\n    ['The Second Floor','Elevator Out of Order'],['DJ Kettle','Steam'],['Moshe and the Roots','Thirsty'],['Night Bus 5','Last Stop Jaffa'],\n    ['The Sunscreen Boys','Factor Fifty'],[\"Grandma's Wi-Fi\",'Password Is on the Fridge'],['Mediterranean Static','Signal Lost']];\n  const ADS = [\n    'NESflicks: a thousand films, and you will spend the evening choosing. Still there?',\n    'Tonight on 8bitTV, Channel 8: the news, in sixteen colours.',\n    'RGBeat, Channel 6: music clips all day. Red, green, blue, repeat.',\n    'Boolify: is this song good? True. Can you skip it? Ask again in 2031.',\n    'PicSell on Herzl Street: pictures, posters and printed shirts. If it holds still, we print it.',\n    'Hungry? ateBite. The whole of Shuk Shalom at your door in thirty minutes. Tip your courier. Seriously.',\n    'Everything Else: the store for everything else. Food? Next door, at the shuk.',\n    'Tired? Cooola. Very tired? Two Cooolas. Cooola: wake up, aggressively.',\n    'New! Cooola Zero Sleep. Same lightning, no bedtime. Ask your doctor. Actually, do not.',\n    'HummusPrime: fresh hummus, delivered by drone. Because chickpeas deserve wings.',\n    \"Wee Laddie Virgin Scotch. For kids. You won't believe it's not alcohol. Neither will your teachers.\",\n    'Tonight at nine, A Butcher Is Born! Can Grandpa Moti stay undefeated? Never gory. Always tender.',\n    'Tahini Tower Savings Bank. We keep your money smooth, nutty, and slightly bitter.',\n    'Yalla Yoga, on Dizengoff. Stretch like nobody is watching. Somebody is watching. Namaste.',\n    'FluffNap pillows. Sleep so deep your neighbors will check on you. FluffNap!',\n    'Herzl Hardware: if it squeaks, leaks or creaks, we have the thing. Probably.',\n    'Kfar Kofi instant coffee. Ninety seconds from kettle to personality.'];\n  const BRAND_TAGS = ['Cooola','ateBite','HummusPrime','Tahini Tower Savings Bank','FluffNap pillows','Kfar Kofi','Herzl Hardware','RGBeat','PicSell'];\n  const QUIPS = ['Big if true.','I will read the rest after my coffee.','Good news, for once.','My producer says that is a real story.','Science, everybody.','Wild times.'];\n  // Boolify takes over on the half hours unless the story has picked a station: a station that only knows two answers\n  const boolifyOn = () => CUR_MEDIA === 'boolify' || (CUR_MEDIA !== 'herzl' && Math.floor(NOW() / 1800000) % 2 === 1);\n  const BOOLIFY_LINES = ['Boolify. Is this song good? True. The next one? Also true. We have never said false.', 'You are on the free tier of Boolify. Your next skip is available in 2031.',\n    'Boolify asks: do you like this song? Yes or no. Maybe is a premium feature.', 'Because you listened to one song, Boolify made you a playlist of that song.', 'Boolify. All of your music, in ones and zeros. Mostly zeros.', 'This hour on Boolify: love songs, if and only if you are in love.'];\n  function dj(){ if (boolifyOn()) return {id:'dj_bool', name:'Boolify', show:'Boolify'}; const h = hourNow(); return h >= 6 && h < 12 ? {id:'dj_benny', name:'Benny Boom', show:'the Wake-Up Call'}\n    : h >= 12 && h < 19 ? {id:'dj_shira', name:'Shira Gold', show:'the Afternoon Drive'} : {id:'dj_yoni', name:'Night Owl Yoni', show:'Night Owls'}; }\n  function djLine(seg){\n    if (boolifyOn()) return BOOLIFY_LINES[Math.floor(hash(seg * 37 + 5) * BOOLIFY_LINES.length)];\n    const d = dj(), r = k => hash(seg * 31 + k), pickOf = (arr, k) => arr[Math.floor(r(k) * arr.length)];\n    const song = BANDS[seg % BANDS.length], nextSong = BANDS[(seg + 1) % BANDS.length], live = Sound.streaming();\n    const W8 = WORLD || {}, wx = W8.weather, heads = (W8.headlines || []).filter(Boolean), sh = W8.shabbat;\n    const kinds = ['song','ad','weather','news','ad','song','time','ad','news'];\n    if (sh && /^(Fri|Sat)/.test(sh.startLabel || '') ) kinds.push('shabbat');\n    let kind = kinds[seg % kinds.length];\n    if (kind === 'weather' && !wx) kind = 'time'; if (kind === 'news' && !heads.length) kind = 'song';\n    { const pl = promoDJ(seg); if (pl && r(23) < .3) return pl; }   // the Pump House's promotions on the radio\n    const hello = r(3) < .4 ? `${d.name} here, on ${d.show}. ` : '';\n    const tag = r(9) < .45 ? ` This ${['song','news','hour','minute'][Math.floor(r(11)*4)]} is brought to you by ${pickOf(BRAND_TAGS, 13)}.` : '';\n    { const today = pack('radio'); if (today.length && r(19) < .45) return hello + pickOf(today, 21); }\n    if (kind === 'song' && live) return `${hello}More ${live.tag} on Radio Herzl, 88.2. All music, no opinions. Except mine.${tag}`;\n    if (kind === 'song') return `${hello}That was ${song[0]} with \"${song[1]}\". Coming up: ${nextSong[0]}. Radio Herzl, 88.2!${tag}`;\n    if (kind === 'weather') return `${hello}${Math.round(wx.temp)} degrees and ${wx.desc} in Tel Aviv. ` + (wx.rain ? 'Umbrellas out, people.' : wx.temp >= 27 ? \"Hydrate. That's an order.\" : wx.temp <= 14 ? 'Find a sweater.' : 'Honestly? Lovely.') + tag;\n    if (kind === 'news') return `${hello}In the news: ${pickOf(heads, 5)}. ${pickOf(QUIPS, 7)}`;\n    if (kind === 'ad') return `A word from our sponsors. ${ADS[Math.floor(r(17) * ADS.length)]}`;\n    if (kind === 'time') return `${hello}It's ${fmtHM.format(new Date(NOW()))} on Radio Herzl. If you're stuck in traffic on the Ayalon, we're sorry. We are too.${tag}`;\n    return `${hello}Shabbat comes in ${sh.startLabel} and goes out ${sh.endLabel}. Shabbat shalom from Radio Herzl!`;\n  }\n  function radioTick(){\n    const playing = UNLOCKED.has('radio') && actor.loc==='apartment' && actor.action==='listening' && !actor.travelling && !actor.hidden && !actor.switching;\n    if (!playing){ if (RADIO.on){ RADIO.on = false; Sound.duck(false); $('stMusic').textContent = ''; if (SAY.who==='radio') SAY.until = 0; } return; }\n    const live = Sound.streaming(), CYCLE = live ? 240000 : 80000, talkAt = live ? 200 : 62;   // live music: the DJ talks every 4 minutes\n    const now = NOW(), seg = Math.floor(now / CYCLE), into = (now % CYCLE) / 1000;\n    if (!RADIO.on){ RADIO.on = true; RADIO.seg = seg; }\n    if (seg !== RADIO.seg){ RADIO.seg = seg; if (!live) Sound.newSong(); }\n    const want = radioPick(); if (live && want && want.url !== live.url) Sound.restartAmb();   // station change\n    $('hudAction').textContent = boolifyOn() ? 'BOOLIFY' : 'RADIO HERZL 88.2';\n    $('stMusic').textContent = live ? `\\u266A ${live.name} (via radio-browser.info)` : '';\n    if (into >= talkAt && into < talkAt + 14 && RADIO.spoken !== seg && NOW() > MEDIA_UNTIL){\n      RADIO.spoken = seg; const d = dj(), text = djLine(seg);\n      Sound.duck(true); showSay('radio', d.name.toUpperCase() + ': ' + text); holdSay(14000);\n      const back = setTimeout(() => Sound.duck(false), 15000);\n      if (Sound.speaking()) Sound.say(d.id, text).then(() => { clearTimeout(back); Sound.duck(false); });\n    }\n  }\n  setInterval(radioTick, 1000);\n  // ---- now and then (every 20-30 s) a small sound from what Ishai is doing; never over someone talking ----\n  const SFX = { working:['type','type','type','mouse','chair'], gaming:['game','game','type'], reading:['page','page','chair'], watching:['remote','chair'],\n    listening:['chair'], cooking:['sizzle','clink'], eating:['clink','crunch'], drinking:['sip','clink'], walking:['steps'], idle:['steps','chair','phone'],\n    sleeping:['snore'], waking:['chair'], exercising:['breath','steps'] };\n  // one small sound in every 25 s slot; the slot picks when and which, so all viewers hear the same one\n  const SFX_SLOT = 25000; let sfxDone = 0;\n  setInterval(() => {\n    const now = NOW(), slot = Math.floor(now / SFX_SLOT), at = slot * SFX_SLOT + hash(slot * 3 + 7) * 8000;\n    if (slot === sfxDone || now < at || now > at + 6000) return;\n    if (now - TALK_AT < 5000 || SPEAKING || Sound.busy() || SAY.who && NOW() < SAY.until || actor.switching || (actor.hidden && !BATH.has(actor.action)) || actor.loc === 'offscreen' || studioOn || showOn || callOn) return;\n    sfxDone = slot;\n    const dogHere = UNLOCKED.has('dog') && dog.loc === actor.loc && actor.action !== 'sleeping';\n    const HOME_SFX = {keys:['keys'], sweep:['sweep'], wipe:['wipe'], dishes:['splash','clink'], snack:['sizzle'], laundry:['page'], scroll:['mouse'], bedphone:['mouse'], read:['page'], kettle:['clink']};\n    let list = actor.travelling ? ['steps'] : actor.err && HOME_SFX[actor.err.tag] ? HOME_SFX[actor.err.tag] : (SFX[actor.action] || []);\n    if (actor.loc === 'bar') list = list.concat(['clink']);\n    if (dogHere && hash(slot * 11 + 2) < .25) list = ['bark'];\n    if (actor.action === 'sleeping' && hash(slot * 13 + 3) < .5) return;   // a quiet night now and then\n    if (list.length) Sound.sfx(list[Math.floor(hash(slot * 5 + 1) * list.length)]);\n  }, 1000);\n  // the bar's and the café's music: show what is playing\n  setInterval(() => { if (RADIO.on) return; const st = (actor.loc==='bar' || actor.loc==='cafe') ? Sound.streaming() : null;\n    $('stMusic').textContent = st ? `\\u266A ${st.name}` : ''; }, 2000);\n  // ================= live from the studio: an hourly recap by the hosts, picture-in-picture =================\n  let STUDIO = null; const studioDone = new Set(); let studioOn = false, studioWho = null;\n  const pipCv = $('pipCv'), pctx = pipCv.getContext('2d');\n  const studioScreen = () => { R(21,4,22,14,'#ff9ad0'); R(22,5,20,12,'#2a1f5a'); };   // the show's logo screen: an eye\n  const studioEye = () => { R(27,9,10,4,'#f4f1ff'); R(28,8,8,1,'#f4f1ff'); R(28,13,8,1,'#f4f1ff'); R(31,9,3,4,'#1d1238'); R(31,9,1,1,'#9fd0ff'); };\n  function drawStudio(t, into){\n    const prev = g; g = into || pctx;\n    R(0,0,64,40,'#1d1238'); for (let x=2;x<64;x+=8) R(x,0,1,29,'#25174a');\n    [10,32,54].forEach((x,i)=>{ R(x-2,0,4,2,'#444'); alpha(.12 + .05*((Math.floor(t/500)+i)%2),()=>R(x-6,2,12,26,'#fff6d8')); });\n    studioScreen(); studioEye();\n    person(HOSTS.zohar.look, 9, 11, t, {legs:false, face:1, talking: studioWho==='zohar', seed:21});\n    person(HOSTS.oren.look, 45, 11, t + 700, {legs:false, face:-1, talking: studioWho==='oren', seed:22});\n    R(0,29,64,1,'#c9b37a'); R(0,30,64,10,'#3a2a5a'); R(0,33,64,1,'#ff9ad0'); R(0,35,64,1,'#9fd0ff');\n    R(18,26,3,3,'#f2f2f2'); R(19,27,1,1,'#8a5a3a'); cooolaCan(42,24);                 // her coffee, his (sponsored) Cooola\n    g = prev;\n  }\n  // a timed list of spoken lines; lead = before the first line, pad = after each line, tail = after the last\n  function spoken(lines, lead, pad, tail){\n    let t = lead; const items = lines.map(l => { const it = {l, at: t, ms: lineMs(l.say)}; t += it.ms + pad(l.say); return it; });\n    return {items, ms: t + tail};\n  }\n  const STUDIO_TIMES = lines => spoken(lines, 1200, say => 1400 + Math.min(2500, say.length * 25), 0);\n  const SHOW_TIMES = lines => spoken(lines, 800, say => 1200 + Math.min(2500, say.length * 25), 1500);\n  const CALL_TIMES = lines => spoken(lines, 2200, say => 900 + Math.min(2200, say.length * 22), 1200);\n  const momentAt = T => { let m = null; for (const x of TL.values()){ if (x.start <= T) m = x; else break; } return m; };\n  const talkBetween = (a, b) => [...TL.values()].some(x => x.plan.length && x.start < b && x.end > a);\n  // the first time from `from` that fits. undefined = not found yet, still looking; null = it never fitted\n  function slotAfter(from, maxWait, fits){\n    for (let T = from; T <= from + maxWait; T += 15000){ if (T > NOW()) return undefined; if (fits(T)) return T; }\n    return null;\n  }\n  const arrivedBy = (m, T) => T - m.start > 20000 || momentAt(m.start - 1)?.ev.location === m.ev.location;\n  // the two hourly recaps take turns: the picture-in-picture on even hours, the full studio break on odd hours\n  function studioStart(st){\n    if (!st || Math.floor(st.t / 3600000) % 2) return null;\n    return slotAfter(st.t, 15 * 60000, T => { const m = momentAt(T); return storyHour(T) >= 8 && m && !m.ev.with && arrivedBy(m, T) && !['phoning','sleeping'].includes(m.ev.action) && !talkBetween(T, T + 1); });\n  }\n  function showStart(sh){\n    if (!sh || !(Math.floor(sh.t / 3600000) % 2)) return null;\n    return slotAfter(sh.t, 20 * 60000, T => { const m = momentAt(T), h = storyHour(T);\n      if (!m || h < 8 || h >= 23.5 || m.ev.action === 'sleeping' || m.ev.with || !arrivedBy(m, T) || talkBetween(T - 90000, T + 180000)) return false;    // quiet for 1.5 minutes, and for 3 more\n      return ![...TL.values()].some(x => x.start > T && x.start <= T + 180000 && (x.ev.with || (x.ev.location || 'apartment') !== (m.ev.location || 'apartment'))); });\n  }\n  function callStart(c){\n    let from = c.t;\n    for (const [at, ms] of [[studioStart(STUDIO), STUDIO ? STUDIO_TIMES(STUDIO.lines).ms + 1000 : 0], [showStart(SHOW), SHOW ? SHOW_TIMES(SHOW.lines).ms : 0]]){\n      if (at === undefined) return undefined;      // wait: the recap goes first\n      if (at !== null && at + ms > from && at < c.t + 12 * 60000) from = at + ms;\n    }\n    return slotAfter(from, 12 * 60000, T => { const m = momentAt(T); return m && m.ev.action !== 'sleeping' && arrivedBy(m, T) && !talkBetween(T, T + 1); });\n  }\n  async function playStudio(st, start){\n    const times = STUDIO_TIMES(st.lines);\n    studioDone.add(st.id); studioOn = true; const pip = $('pip'), cap = $('pipCap'); cap.textContent = '';\n    const anim = () => { if (!studioOn) return; drawStudio(wall()); requestAnimationFrame(anim); }; anim();\n    pip.classList.add('on');\n    for (let i = 0; i < times.items.length; i++){\n      const it = times.items[i], l = it.l, at = start + it.at; await untilT(at); const late = NOW() - at;\n      if (late >= it.ms){ addMsg({id: st.id + ':' + i, t: st.t, who: l.who, say: l.say, host: true}, false); continue; }\n      studioWho = l.who; Sound.hush();\n      cap.innerHTML = ''; const b = document.createElement('b'); b.style.color = HOSTS[l.who].color; b.textContent = HOSTS[l.who].name + ': ';\n      const tx = document.createElement('span'); cap.append(b, tx);\n      if (late < 800) Sound.say(l.who, l.say);\n      addMsg({id: st.id + ':' + i, t: st.t, who: l.who, say: l.say, host: true}, false);\n      await typeInto(tx, l.say, true, ch => { Sound.blip(l.who, ch); cap.scrollTop = cap.scrollHeight; }, {at});\n      await untilT(at + it.ms); studioWho = null;\n    }\n    await untilT(start + times.ms);\n    pip.classList.remove('on'); await new Promise(r => setTimeout(r, 1000)); studioOn = false;\n  }\n  setInterval(() => {\n    const st = STUDIO; if (!st || studioOn || showOn || studioDone.has(st.id) || DEV_ONLY_NARRATION_SKIP()) return;\n    const at = studioStart(st); if (at === undefined) return;\n    if (at === null || NOW() >= at + STUDIO_TIMES(st.lines).ms) studioDone.add(st.id); else playStudio(st, at);\n  }, 1000);\n  function DEV_ONLY_NARRATION_SKIP(){ return !!forceLoc; }   // previews stay clean\n  // ================= commercial breaks: sliding banners for fake brands and Watch-Ishai merch =================\n  // Only when it is quiet (he is alone, or asleep); every 6 minutes, same banner for every viewer.\n  const adCv = $('adCv'), actx = adCv.getContext('2d');\n  const EYE = (x,y) => { R(x+1,y,6,1,'#f4f1ff'); R(x,y+1,8,3,'#f4f1ff'); R(x+1,y+4,6,1,'#f4f1ff'); R(x+3,y+1,2,3,'#1d1238'); R(x+3,y+1,1,1,'#9fd0ff'); };\n  const BANNERS = [\n    {bg:COOOLA.bg, fg:COOOLA.fg, title:'Sponsored by COOOLA', sub:'Something to drink about.', draw(t){ R(0,0,40,20,COOOLA.dark); for (let i=0;i<3;i++) R(4+i*12,4,7,12,COOOLA.bg), R(4+i*12,8,7,2,COOOLA.fg), R(4+i*12,4,7,1,'#c9ced4'); bolt(16+Math.floor(t/300)%2,6,COOOLA.bolt); }},\n    {bg:'#7a1020', fg:'#ffd36a', title:'A BUTCHER IS BORN · tonight 21:00', sub:'Can Grandpa Moti stay undefeated? Never gory. Always tender.', draw(t){ R(0,0,40,20,'#3a0a10'); const a=Math.floor(t/250)%2;\n      R(8,6-a,14,7,'#c9ced4'); R(8,6-a,14,1,'#f4f4f4'); R(20,9-a,8,3,'#5a3a2a'); R(10,8-a,2,2,'#3a0a10'); R(26,13,10,5,'#c0504a'); R(27,14,8,1,'#f2c0b0'); }},\n    {bg:'#1d1238', fg:'#ff9ad0', title:'Official WATCH-ISHAI tee', sub:'\"I watched Ishai water Moshe.\" 100% cotton, 0% privacy.', draw(t){ R(0,0,40,20,'#2a1f5a');\n      R(12,4,16,14,'#f4f1ff'); R(8,4,5,5,'#f4f1ff'); R(27,4,5,5,'#f4f1ff'); R(17,4,6,1,'#2a1f5a'); EYE(16